package com.beyondsignal.game.event; import static org.junit.jupiter.api.Assertions.*; import com.beyondsignal.game.galaxy.*; import java.util.*; import org.junit.jupiter.api.Test; class ExplorationEventControllerTest{ @Test void storesResolvedEvent(){ var c=new ExplorationEventController(); var s=new StarSystem("sol","Sol",new Coordinates(0,0,0),"G",List.of(),true,false,false,false); var e=c.generate(s,5,9); var x=c.resolve(e.id(),e.choices().getFirst(),12); assertEquals(x,c.log().eventById(e.id()).orElseThrow()); assertTrue(c.log().pendingEvents().isEmpty()); }}
